'use client';

import { useState } from 'react';
import Link from 'next/link';
import { usePathname } from 'next/navigation';
import { List, X, Waveform } from '@phosphor-icons/react';
import { NAV, SITE } from '@/lib/site';
import { btnPrimary } from './ui';

export default function SiteNav() {
  const [open, setOpen] = useState(false);
  const pathname = usePathname();

  return (
    <header className="sticky top-0 z-50 border-b border-white/10 bg-bg/70 backdrop-blur-md">
      <nav className="mx-auto flex h-[68px] w-full max-w-6xl items-center justify-between px-6">
        <Link href="/" className="flex items-center gap-2 font-bold" aria-label={`${SITE.name} home`}>
          <span className="grid h-8 w-8 place-items-center rounded-lg bg-accent text-on-accent">
            <Waveform size={20} weight="bold" aria-hidden />
          </span>
          <span className="text-lg">{SITE.name}</span>
        </Link>

        <ul className="hidden items-center gap-7 md:flex">
          {NAV.map((item) => {
            const active = pathname === item.href || pathname.startsWith(item.href + '/');
            return (
              <li key={item.href}>
                <Link
                  href={item.href}
                  className={`text-sm font-medium transition ${
                    active ? 'text-text' : 'text-muted hover:text-text'
                  }`}
                >
                  {item.label}
                </Link>
              </li>
            );
          })}
        </ul>

        <div className="flex items-center gap-3">
          <Link href="/practice" className={`${btnPrimary} hidden md:inline-flex`}>
            Start free
          </Link>
          <button
            type="button"
            className="grid h-10 w-10 place-items-center rounded-lg border border-white/15 text-text md:hidden"
            aria-label={open ? 'Close menu' : 'Open menu'}
            aria-expanded={open}
            onClick={() => setOpen((v) => !v)}
          >
            {open ? <X size={22} aria-hidden /> : <List size={22} aria-hidden />}
          </button>
        </div>
      </nav>

      {open ? (
        <div className="border-t border-white/10 bg-bg2 md:hidden">
          <ul className="mx-auto flex w-full max-w-6xl flex-col px-6 py-2">
            {NAV.map((item) => (
              <li key={item.href}>
                <Link
                  href={item.href}
                  className="block border-b border-white/5 py-3 text-text"
                  onClick={() => setOpen(false)}
                >
                  {item.label}
                </Link>
              </li>
            ))}
            <li className="pt-3">
              <Link href="/practice" className={btnPrimary} onClick={() => setOpen(false)}>
                Start free
              </Link>
            </li>
          </ul>
        </div>
      ) : null}
    </header>
  );
}
